package local.lito381.server;
import java.util.*;
/** Actual detached first-discovery members and signed/healing consumers; no bound Hub discovery or HP/IO. */
public final class SourceFirstPlayersPlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}
 static NativeAreaMaterialAction.Context context()throws Exception{return(NativeAreaMaterialAction.Context)SourceSignedRecoveryPlan.unsafe().allocateInstance(NativeAreaMaterialAction.Context.class);}
 public static void main(String[]args)throws Exception{
  var hub=(GameHub)SourceSignedRecoveryPlan.unsafe().allocateInstance(GameHub.class);var pc=SourceSignedRecoveryPlan.shell(hub,"first-target");var other=SourceSignedRecoveryPlan.shell(hub,"entrant");var binding=NativePlayerCommit.Binding.capture(pc);Object life=NativeSourceControlledDisplay.token(pc);var c=context();NativeSourceFirstPlayers.remember(c,pc,binding,life);check(c.nativeSourceFirstPlayers instanceof NativeSourceFirstPlayers.Builder,"first capture has one bounded original Context builder");check(NativeSourceFirstPlayers.member(pc,binding,c)==null,"unpublished constructor builder cannot become fresh submission authority");NativeSourceFirstPlayers.seal(c);var snapshot=(NativeSourceFirstPlayers.Snapshot)c.nativeSourceFirstPlayers;var first=snapshot.members().get(pc);check(first!=null&&first.life==life&&first.current(true),"actual original Member keeps life frozen before binding");check(NativeSourceSignedRecovery.member(pc,binding,c)==first,"actual final shared signed fallback borrows exact first-discovery Member");check(NativeSourceSignedRecovery.member(other,NativePlayerCommit.Binding.capture(other),c)==null,"missing later entrant cannot be freshly adopted");
  var changed=new NativePlayerCommit.Binding(binding.owner(),binding.object(),binding.source(),binding.account(),"other-role",binding.phase(),binding.room(),binding.map(),binding.instance());check(NativeSourceSignedRecovery.member(pc,changed,c)==null,"same object cannot rebind original member to another role");var state=CombatAccess.field(CombatAccess.field(pc,"timedStatus"),"sourcePoisonLifecycle");SourceSignedRecoveryPlan.set(state,"sourceNpcOwner",new Object());check(NativeSourceSignedRecovery.member(pc,binding,c)==first&&!first.current(false),"revival after original Hub discovery cannot be recaptured as a new live target");var afterBinding=NativePlayerCommit.Binding.capture(pc);var between=context();NativeSourceFirstPlayers.remember(between,pc,afterBinding,life);NativeSourceFirstPlayers.seal(between);var stale=NativeSourceSignedRecovery.member(pc,afterBinding,between);check(stale.life==life&&!stale.current(false),"life change between frozen token and original binding capture is rejected");SourceSignedRecoveryPlan.set(state,"sourceNpcOwner",life);
  SourceSignedRecoveryPlan.set(pc,"selectedCharacter","replacement");check(NativeSourceSignedRecovery.member(pc,binding,c)==first&&!first.current(false),"owner role replacement retains old stale proof rather than new role");SourceSignedRecoveryPlan.set(pc,"selectedCharacter","first-target");SourceSignedRecoveryPlan.set(pc,"selectedClassicServerName","other-source");check(!first.current(false),"source replacement cannot inherit first capture");SourceSignedRecoveryPlan.set(pc,"selectedClassicServerName","detached-source");SourceSignedRecoveryPlan.set(pc,"account","other-account");check(!first.current(false),"account replacement cannot inherit first capture");SourceSignedRecoveryPlan.set(pc,"account","detached-account");SourceSignedRecoveryPlan.set(pc,"positionX",30);check(!first.current(true)&&first.current(false),"original pose is frozen for new casts without adding a position gate to admitted HP");SourceSignedRecoveryPlan.set(pc,"positionX",0);
  var child=context();NativeSourceFirstPlayers.inherit(child,c);check(child.nativeSourceFirstPlayers==snapshot&&NativeSourceSignedRecovery.member(pc,binding,child)==first,"original Context copy shares immutable first proof instead of recapturing");try{snapshot.members().put(other,first);throw new AssertionError("mutable snapshot");}catch(UnsupportedOperationException expected){check(true,"published first-player snapshot is immutable");}var duplicate=context();NativeSourceFirstPlayers.remember(duplicate,pc,binding,life);SourceSignedRecoveryPlan.set(state,"sourceNpcOwner",new Object());NativeSourceFirstPlayers.remember(duplicate,pc,NativePlayerCommit.Binding.capture(pc),NativeSourceControlledDisplay.rawLife(pc));NativeSourceFirstPlayers.seal(duplicate);check(NativeSourceSignedRecovery.member(pc,binding,duplicate).life==life,"duplicate roster occurrence cannot replace first life");SourceSignedRecoveryPlan.set(state,"sourceNpcOwner",life);
  var raw=(NativeSourceRawDamage.Action)SourceSignedRecoveryPlan.unsafe().allocateInstance(NativeSourceRawDamage.Action.class);var older=new NativeSourceRawDamage.Member(pc,binding,new Object());SourceSignedRecoveryPlan.set(raw,"members",new IdentityHashMap<>(Map.of(pc,older)));SourceSignedRecoveryPlan.set(c,"nativeSourceRawAction",raw);check(NativeSourceSignedRecovery.member(pc,binding,c)==older,"earlier raw ingress proof keeps precedence over Context discovery");SourceSignedRecoveryPlan.set(c,"nativeSourceRawAction",null);var actor=new NativeSourceDamageDisplay.Actor(pc,binding,new Object(),0,0);SourceSignedRecoveryPlan.set(c,"nativeSourceMagicSnapshot",new NativeSourceMagicNpc.Snapshot(actor,Map.of(),List.of(),Map.of(),Map.of()));check(NativeSourceSignedRecovery.member(pc,binding,c).life==actor.life(),"earlier magic source proof keeps its original life");SourceSignedRecoveryPlan.set(c,"nativeSourceMagicSnapshot",null);
  var lifetime=(NativePlayerLifetime)SourceSignedRecoveryPlan.unsafe().allocateInstance(NativePlayerLifetime.class);SourceSignedRecoveryPlan.set(lifetime,"admission",new Object());SourceSignedRecoveryPlan.set(lifetime,"mode",NativePlayerLifetime.Mode.OPEN);var cast=new NativeSourceHealingCast.Cast(first,hub,lifetime,Map.of(pc,first));SourceSignedRecoveryPlan.set(c,"nativeSourceHealingCast",cast);check(NativeSourceSignedRecovery.member(pc,binding,c)==first,"existing healing cast proof still has original precedence");cast.close();check(NativeSourceSignedRecovery.member(pc,binding,c)==null,"closed healing cast never falls through to older or fresh capture");SourceSignedRecoveryPlan.set(c,"nativeSourceHealingCast",null);
  var empty=context();empty.nativeSourceFirstPlayers=new NativeSourceFirstPlayers.Snapshot(Map.of());check(NativeSourceSignedRecovery.member(pc,binding,empty)==null,"published empty discovery remains fail closed");var unmarked=context();check(NativeSourceSignedRecovery.member(pc,binding,unmarked)!=first&&NativeSourceSignedRecovery.member(pc,binding,unmarked).current(false),"unmarked/WORLD original fresh fallback remains");check(NativeSourceSignedRecovery.member(pc,binding,null).current(false),"original no-Context ingress still captures before its own pair wait");var incomplete=context();NativeSourceFirstPlayers.remember(incomplete,pc,binding,life);var unpublished=context();NativeSourceFirstPlayers.inherit(unpublished,incomplete);check(NativeSourceSignedRecovery.member(pc,binding,unpublished)==null,"unpublished parent builder cannot be inherited as new authority");
  for(var type:List.of(NativeSourceFirstPlayers.Builder.class,NativeSourceFirstPlayers.Snapshot.class))check(Arrays.stream(type.getDeclaredFields()).noneMatch(f->f.getType()==NativeAreaMaterialAction.Context.class||f.getType()==GameHub.class||f.getType()==NativeSourceHealingCast.Cast.class),"snapshot has no Context/Hub/cast back-reference");check(NativeAreaMaterialAction.current.get()==null,"first-discovery helpers require no new ThreadLocal or current-context installation");System.out.println("PASS"+cases+" first-discovery life-before-binding/immutable-copy/actual-signed-healing-priority/role-source-account-revival contracts; no bound Hub discovery/HP/role/IO/Main/database/game qualification");
 }
}
